code='''from collections import Counter, deque


def transform(grid):
    rows, cols = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    outside = [[False] * cols for _ in range(rows)]
    queue = deque()
    for r in range(rows):
        for c in (0, cols - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                queue.append((r, c))
    for c in range(cols):
        for r in (0, rows - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < rows and 0 <= nc < cols and not outside[nr][nc] and grid[nr][nc] == background:
                outside[nr][nc] = True
                queue.append((nr, nc))
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background and not outside[r][c]:
                result[r][c] = 4
    return result
